"""Escaped, standalone HTML report with an explicit usage-preview control."""
import html


def html_report(report):
    esc = lambda value: html.escape(str(value), quote=True)
    context, counts = report['context'], report['counts']
    percentage = context['percentage']
    initial = min(100, percentage) if percentage is not None else 0
    label = f'{percentage:.0f}%' if percentage is not None else 'Unknown'
    cards = ''.join(f'<article class="metric"><span>{title}</span><strong>{counts[key]:,}</strong><small>{note}</small></article>' for title, key, note in [
        ('Source text', 'raw_text_tokens', 'BPE tokens in supplied text'),
        ('Normalized text', 'normalized_text_tokens', 'BPE tokens after the NLP pipeline'),
        ('Content terms', 'content_terms', 'After stop-word removal'),
        ('Unique stems', 'unique_stems', 'Lexical diversity, not context size')])
    rows = ''.join(f'<tr><td>{esc(b["location"])}</td><td>{b["text_tokens"]:,}</td><td>{b["lexical_overlap"]:.0%}</td><td>{esc("; ".join(b["reasons"]))}</td></tr>' for b in report['candidates'])
    if not rows:
        rows = '<tr><td colspan="4">No eligible blocks. Keep the context intact until a useful boundary.</td></tr>'
    protected = sum(bool(b['protected']) for b in report['blocks'])
    terms = ''.join(f'<span class="term">{esc(t["term"])} <b>{t["count"]}</b></span>' for t in report['top_stems'])
    limitations = ''.join(f'<li>{esc(s)}</li>' for s in report['limitations'])
    policy = report['policy']
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Context Bloom · make room for what matters</title><style>
:root{{--ink:#e9eee7;--muted:#a7b4a9;--green:#bcf2a1;--surface:#19231f;--line:#344239}}
*{{box-sizing:border-box}}body{{margin:0;background:#101a16;color:var(--ink);font:16px/1.6 system-ui,sans-serif}}main{{max-width:1180px;margin:auto;padding:32px 36px 70px}}nav{{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:24px}}.brand{{font-weight:700;letter-spacing:-.04em;font-size:24px}}.pill{{border:1px solid #50684d;border-radius:30px;padding:6px 14px;font-size:11px;letter-spacing:.12em;color:var(--green)}}.hero{{display:grid;grid-template-columns:1.35fr 1fr;gap:40px;align-items:center;margin:64px 0 38px}}.eyebrow{{font:12px monospace;text-transform:uppercase;letter-spacing:.12em;color:var(--green)}}h1{{font-size:clamp(44px,6vw,76px);line-height:1.04;letter-spacing:-.065em;margin:20px 0}}h1 em{{font-family:Georgia,serif;font-weight:400;color:var(--green)}}p{{color:var(--muted);max-width:600px}}.orb-space{{height:290px;display:grid;place-items:center;position:relative}}.orbit{{width:270px;height:270px;border:1px solid #40523c;border-radius:50%;position:absolute}}.orbit:after{{content:'';position:absolute;inset:30px;border:1px dashed #40523c;border-radius:50%}}#orb{{width:130px;height:130px;border-radius:50%;background:radial-gradient(circle at 30% 22%,#edf9bd 0,#b9ed9d 25%,#729d79 65%,#354d43 100%);box-shadow:0 0 50px #b2efa31c,inset -8px -10px 30px #101a1655;transition:width .5s,height .5s;display:grid;place-content:center;text-align:center;z-index:1;color:#16251b}}#orb strong{{font-size:30px}}#orb small{{font-size:11px}}.control{{background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:20px}}.control label{{font-size:12px;color:var(--muted)}}input[type=range]{{width:100%;accent-color:var(--green);margin:16px 0}}button{{background:transparent;color:var(--green);border:1px solid #50684d;border-radius:20px;padding:7px 14px;cursor:pointer}}button:focus-visible,input:focus-visible{{outline:2px solid #f3cc8a;outline-offset:4px}}#mode{{font-size:12px;min-height:40px}}.metrics{{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:30px 0 50px}}.metric{{border:1px solid var(--line);border-radius:14px;padding:22px 18px;background:var(--surface)}}.metric span,.metric small{{display:block;color:var(--muted);font-size:12px}}.metric strong{{display:block;font-size:34px;margin:8px 0;letter-spacing:-.04em}}h2{{font-size:28px;letter-spacing:-.04em}}.section-head{{display:flex;align-items:center;justify-content:space-between;gap:16px}}.table-wrap{{overflow:auto}}table{{width:100%;border-collapse:collapse;min-width:600px}}td,th{{padding:17px 12px;border-bottom:1px solid var(--line);text-align:left}}th{{font:11px monospace;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}}td{{font-size:14px}}td:first-child{{color:var(--green);white-space:nowrap}}.term{{display:inline-block;background:#202e24;border:1px solid var(--line);border-radius:30px;padding:5px 14px;margin:4px;font-size:13px}}.term b{{color:var(--green);margin-left:8px}}.note{{border-left:2px solid #e2c28a;padding:8px 22px;margin:42px 0;background:#202820}}details{{color:var(--muted);margin-top:35px}}footer{{margin-top:45px;border-top:1px solid var(--line);padding-top:22px;font-size:12px;color:var(--muted)}}@media(max-width:760px){{main{{padding:24px 18px}}.hero{{grid-template-columns:1fr;margin-top:36px;gap:20px}}.metrics{{grid-template-columns:repeat(2,1fr)}}.pill{{font-size:9px}}.section-head{{align-items:start;flex-direction:column}}}}@media(prefers-reduced-motion:reduce){{#orb{{transition:none}}}}
</style></head><body><main><nav><div class="brand">◌ context bloom</div><span class="pill">LOCAL FIRST · AGENT SKILL</span></nav>
<section class="hero"><div><div class="eyebrow">A little breathing room for your agent</div><h1>Keep the meaning.<br><em>Let the noise go.</em></h1><p>{esc(report['advice'])}</p><p>Context pressure and lexical density, measured separately. A reviewable plan for what to condense and what to keep.</p></div><div><div class="orb-space"><div class="orbit"></div><div id="orb"><strong id="usage">{label}</strong><small>context used</small></div></div><div class="control"><label for="pressure">Explore bubble sizes · preview only</label><input id="pressure" type="range" min="0" max="100" value="{initial}" aria-describedby="mode"><div id="mode">Snapshot: {esc(context['source'])}</div><button id="restore" type="button">Restore report reading</button></div></div></section>
<div class="metrics">{cards}</div><section><div class="section-head"><h2>Where to make room</h2><span class="pill">{protected} BLOCKS PROTECTED</span></div><p>Review these older blocks first. Overlap is a lexical clue, not proof that their meaning is redundant.</p><div class="table-wrap"><table><thead><tr><th>Source</th><th>Text tokens</th><th>Overlap</th><th>Why review it</th></tr></thead><tbody>{rows}</tbody></table></div></section>
<section><h2>What the context keeps talking about</h2>{terms}</section><div class="note"><strong>Condense with care.</strong><p>Preserve the goal, constraints, exact identifiers, decisions, and unfinished work. Use the companion handoff worksheet before invoking your agent’s compaction command.</p></div>
<details><summary>Method &amp; limits</summary><p>Encoding: {esc(report['tokenizer']['encoding'])}. English POS-aware lemmatization → stop-word removal → Porter stemming → token count. Negations are retained.</p><ul>{limitations}</ul></details><footer>Context Bloom · formerly Text-Word-Counter · offline report · no live session connection</footer></main>
<script>
const slider=document.getElementById('pressure'),orb=document.getElementById('orb'),usage=document.getElementById('usage'),mode=document.getElementById('mode');
function draw(value){{const size=100+value*1.45;orb.style.width=size+'px';orb.style.height=size+'px';}}
slider.addEventListener('input',()=>{{const v=Number(slider.value);draw(v);usage.textContent=v+'%';mode.textContent='Preview only · '+(v>={policy['compact_at_percent']}?'compact at a safe boundary':v>={policy['prepare_at_percent']}?'prepare a handoff':'room to work');}});
document.getElementById('restore').addEventListener('click',()=>{{slider.value={initial};draw({initial});usage.textContent='{label}';mode.textContent='Report snapshot · '+({str(percentage is not None).lower()}?'user-supplied host usage':'usage unavailable');}});draw({initial});
</script></body></html>'''
